package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaNlDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_allahumma_bika_asbahna" to DuaText("Allahumma Bika Asbahna", "O Allah, door U gaan wij de ochtend in en door U gaan wij de avond in; door U leven wij en door U sterven wij, en voor U is de opstanding.", "In de ochtend.", "De Profeet ﷺ leerde de Metgezellen om deze ochtend en avond te zeggen."),
        "dua_allahumma_bika_amsayna" to DuaText("Allahumma Bika Amsayna", "O Allah, door U gaan we de avond in en door U gaan we de ochtend in; door U leven wij en door U sterven wij, en tot U is de terugkeer.", "In de avond.", "De Profeet ﷺ leerde de Metgezellen om deze ochtend en avond te zeggen."),
        "dua_afiyah_morning" to DuaText("Ik vraag om Afiyah", "O Allah, ik vraag U om vergeving en welzijn in deze wereld en het Hiernamaals.", "De Profeet ﷺ verliet deze dua nooit, 's ochtends of 's avonds.", "Niemand heeft iets beters gekregen dan welzijn."),
        "dua_afini_fi_badani" to DuaText("Gezondheid van lichaam, gehoor en zicht", "O Allah, schenk welzijn aan mijn lichaam. O Allah, schenk welzijn aan mijn gehoor. O Allah, schenk welzijn aan mijn zicht. Er is geen god behalve Jij.", "Drie keer per ochtend en avond.", "Een dua voor de gezondheid en de bescherming van de zintuigen."),
        "dua_ya_hayyu_aslih" to DuaText("Corrigeer al mijn zaken", "O Eeuwig Levende, O Onderhouder, door Uw genade zoek ik hulp: zet al mijn zaken in orde en laat mij zelfs voor een oogwenk niet aan mezelf over.", "De Profeet ﷺ adviseerde Fatimah (RA) om het 's ochtends en 's avonds te zeggen.", "Vragen om de hulp van Allah in elke kwestie."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Tasbeeh van Juwayriyah (RA)", "Glorie zij Allah en alle lof is van Hem – zo veel als Zijn schepping, zoveel als Hem behaagt, gelijk aan het gewicht van Zijn Troon en de inkt van Zijn woorden.", "Drie keer in de ochtend – zwaarder dan uren dhikr.", "Het drie keer zeggen van deze vier zinnen weegt zwaarder dan de dhikr van zonsopgang tot halverwege de ochtend."),
        "dua_salawat" to DuaText("Durood-e-Ibrahimi", "O Allah, stuur gebeden naar Mohammed ﷺ en de familie van Mohammed zoals U gebeden stuurde naar Ibrahim (AS) en de familie van Ibrahim; U bent prijzenswaardig, glorieus. O Allah, zegen Mohammed ﷺ en de familie van Mohammed zoals U Ibrahim (AS) en de familie van Ibrahim zegende; U bent prijzenswaardig, glorieus.", "Salawat op de Profeet ﷺ in gebed en te allen tijde.", "Degene die één keer salawat stuurt, Allah zendt hem tien barmhartigheden (Muslim 408)."),
        "dua_wudu_after" to DuaText("Na Wudu", "Ik getuig dat niemand het recht heeft om aanbeden te worden behalve Allah, alleen, zonder partner, en dat Mohammed (ﷺ) Zijn dienaar en Boodschapper is. O Allah, laat mij behoren tot degenen die berouw tonen en zichzelf zuiveren.", "Na het voltooien van de wudu.", "De acht poorten van het Paradijs worden voor hem geopend, waarheen hij maar wil."),
        "dua_wudu_before" to DuaText("Vóór Wudu", "In de naam van Allah.", "Bij het starten van wudu.", "Er is geen (volledige) wudu voor iemand die de naam van Allah er niet bij vermeldt."),
        "dua_istiftah" to DuaText("Openingssmeekbede (Sana)", "Glorie zij U, O Allah, en alle lof zij U. Gezegend is Uw naam, verheven is Uw majesteit, en er is geen god behalve U.", "Aan het begin van het gebed, direct na de openingstakbir.", "De Sunnah openingsdua van het gebed."),
        "dua_ruku" to DuaText("In Ruko", "Glorie zij mijn Heer, de Grote.", "Minstens drie keer in ruku.", "De Sunnah tasbih van roekoe."),
        "dua_sujood" to DuaText("In Sujood", "Glorie zij mijn Heer, de Allerhoogste.", "Minstens drie keer in sujood.", "De dienaar is het dichtst bij zijn Heer terwijl hij zich ter aarde werpt (Muslim 482)."),
        "dua_rising_ruku" to DuaText("Opstaan uit Ruku", "Allah hoort degene die Hem prijst. Onze Heer, aan U behoort alle lof.", "Terwijl je opstaat uit ruku en rechtop staat.", "Wie zijn 'Rabbana wa lakal-hamd' samenvalt met die van de engelen, zijn zonden uit het verleden zijn vergeven."),
        "dua_between_sajdas" to DuaText("Tussen de twee Sajda's", "Mijn Heer, vergeef mij. Mijn Heer, vergeef mij.", "Terwijl je tussen de twee buigingen zit.", "De Sunnah-dua van het zitten tussen de neerknielingen."),
        "dua_before_salam_four" to DuaText("Toevlucht voor vier dingen (vóór de salam)", "O Allah, ik zoek toevlucht bij U tegen de bestraffing van de hel, tegen de bestraffing van het graf, tegen de beproevingen van leven en dood, en tegen het kwaad van de berechting van de valse Messias (Dajjal).", "Na de laatste tashahhud en salawat, vóór de salam.", "De Profeet ﷺ beval toevlucht te zoeken tegen deze vier dingen."),
        "dua_qunoot_witr" to DuaText("Qunoot in Witr", "O Allah, leid mij onder degenen die U hebt geleid, schenk mij welzijn onder degenen die U welzijn hebt verleend, neem mij onder Uw hoede onder degenen die U onder Uw zorg hebt genomen, zegen mij in wat U hebt gegeven en bescherm mij tegen het kwaad van wat U heeft verordend. U besluit en niemand besluit tegen u, en degene met wie u bevriend raakt, wordt nooit vernederd. Gezegend en Verheven bent U, onze Heer.", "In het Witr-gebed leerde de Profeet ﷺ het aan Hasan ibn Ali (RA).", "De Sunnah-qunoot van witr. (Onder de Hanafi's is 'Allahumma inna nasta'inuka' ook bekend.)"),
        "dua_qunoot_hanafi" to DuaText("Qunoot (Allahumma Inna Nasta'inuka)", "O Allah, wij zoeken Uw hulp en Uw vergeving, wij geloven in U en vertrouwen op U, wij prijzen U op de beste manier, wij danken U en zijn niet ondankbaar, en wij laten iedereen die U ongehoorzaam is in de steek. O Allah, U alleen aanbidden wij, tot U bidden en werpen wij ons neer, naar U haasten wij ons en streven wij ernaar, wij hopen op Uw genade en vrezen Uw bestraffing; Uw bestraffing zal zeker de ongelovigen bereiken.", "In witr – de praktijk van de Hanafi’s.", "Overgeleverd door Umar (RA) in de qunoot."),
        "dua_sleep_aslamtu" to DuaText("Laatste woorden voor het slapen gaan", "O Allah, ik onderwerp mezelf aan U, vertrouw mijn zaak aan U toe en vertrouw mijn rug toe aan Uw bescherming, uit hoop op U en uit angst voor U. Er is geen toevlucht en geen ontsnapping aan U behalve aan U. Ik geloof in Uw Boek dat U hebt geopenbaard en in Uw Profeet die U heeft gezonden.", "Na wudu, liggend op de rechterkant – de allerlaatste woorden voor het slapengaan.", "Als hij die nacht sterft, sterft hij tijdens de fitrah (islam)."),
        "dua_waking_night" to DuaText("'s Nachts wakker worden", "Niemand heeft het recht om aanbeden te worden behalve Allah, alleen, zonder partner. Aan Hem is de heerschappij en aan Hem is de lof, en Hij heeft macht over alle dingen. Alle lof is voor Allah, glorie zij Allah, niemand heeft het recht om aanbeden te worden behalve Allah, Allah is de Grootste en er is geen macht of kracht behalve bij Allah. O Allah, vergeef mij.", "Bij het wakker worden tijdens de nacht.", "Zijn dua wordt verhoord, en als hij wudu doet en bidt, wordt zijn gebed geaccepteerd."),
        "dua_hamm_ibn_masud" to DuaText("Dua voor verdriet (Ibn Mas'ud)", "O Allah, ik ben Uw dienaar, zoon van Uw dienaar, zoon van Uw dienstmaagd. Mijn spie is in Uw hand, Uw bevel over mij wordt uitgevoerd en Uw besluit betreffende mij is rechtvaardig. Ik vraag U bij elke naam die de Uwe is, waarmee U Uzelf noemde, of geopenbaard in Uw Boek, of onderwezen aan iemand van Uw schepping, of bij Uzelf gehouden in de kennis van het ongeziene – dat U de Koran tot de bron van mijn hart maakt, het licht van mijn borst, de verwijdering van mijn verdriet en het vertrek van mijn zorgen.", "Bij verdriet en angst vervangt Allah het verdriet door vreugde.", "Allah neemt zijn zorgen en verdriet weg en schenkt hem daarvoor in de plaats vreugde."),
        "dua_difficulty_sahl" to DuaText("Als iets moeilijk is", "O Allah, niets is gemakkelijk behalve wat U gemakkelijk maakt, en U maakt het moeilijke gemakkelijk als U dat wenst.", "Als iets moeilijk voelt.", "Gemakkelijk bij examens en moeilijke taken."),
        "dua_musibah" to DuaText("Na een ramp (Istirja)", "Wij behoren aan Allah en tot Hem zullen wij terugkeren. O Allah, beloon mij in mijn ellende en vervang het voor mij door iets beters.", "Bij verlies of calamiteit.", "Allah geeft zeker iets beters – Umm Salamah (RA) kreeg de Profeet ﷺ."),
        "dua_debt" to DuaText("Voor verlichting van schulden", "O Allah, geef mij genoeg aan wat U wettig hebt gemaakt tegen wat U onwettig hebt gemaakt, en maak mij door Uw milddadigheid onafhankelijk van alles behalve U.", "Voor het afbetalen van schulden – gegeven door Ali (RA).", "Zelfs als de schuld als een berg is, zal Allah deze vereffenen."),
        "dua_anger" to DuaText("Wanneer boos", "Ik zoek mijn toevlucht bij Allah tegen Shaytan, de vervloekte.", "Wanneer boos.", "De Profeet ﷺ zei: als hij dit zegt, zal zijn woede verdwijnen."),
        "dua_waswasa" to DuaText("Tegen Waswasa in geloof", "Ik geloof in Allah en Zijn boodschappers.", "Wanneer er satanische influisteringen over geloof komen.", "Wanneer het gefluister komt, zeg dit dan en stop daar (en zoek ook toevlucht bij Allah)."),
        "dua_travel_full" to DuaText("Volledige reissmeekbede", "O Allah, wij vragen U op deze reis om gerechtigheid en vroomheid, en om daden die U behagen. O Allah, maak deze reis gemakkelijk voor ons en verkort de afstand. O Allah, U bent de Metgezel op de reis en de Bewaker van het gezin.", "Wanneer u op reis gaat, na 'Subhanalladhi sakhkhara'.", "De volledige Sunnah-reisdua."),
        "dua_return_travel" to DuaText("Terugkerend van reizen", "We keren terug, hebben berouw, aanbidden en prijzen onze Heer.", "Bij terugkomst van een reis.", "De Profeet ﷺ zei dit toen hij terugkeerde van een reis."),
        "dua_farewell_traveller" to DuaText("Afscheid nemen van een reiziger", "Ik vertrouw uw religie, uw vertrouwen en de uitkomst van uw daden toe aan Allah.", "Bij het afscheid nemen van een reiziger.", "Wat aan Allah is toevertrouwd, gaat nooit verloren."),
        "dua_entering_town" to DuaText("Stoppen op een plaats", "Ik zoek toevlucht bij de perfecte woorden van Allah tegen het kwaad van alles wat Hij heeft geschapen.", "Wanneer u op een plaats stopt of in een nieuwe stad aankomt.", "Niets zal hem kwaad doen totdat hij daar vandaan vertrekt."),
        "dua_boarding_ship" to DuaText("Aan boord gaan van een schip/voertuig", "In de naam van Allah is het zeilen en het verankeren ervan. Waarlijk, mijn Heer is Vergevensgezind, Barmhartig.", "Bij het aan boord gaan van een schip of voertuig – de woorden van Profeet Noeh (AS).", "Een koranvers - de dua van Noeh's (AS) ark."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Istighfar met Hayyul-Qayyum", "Ik zoek vergeving bij Allah, buiten wie er geen god is, de Eeuwig Levende, de Onderhouder, en ik wend mij in berouw tot Hem.", "Voor bekering.", "Zijn zonden zijn vergeven, zelfs als hij van het slagveld was gevlucht."),
        "dua_rabbighfir_warham" to DuaText("Rabbighfir Warham", "Mijn Heer, vergeef en heb genade, want U bent de beste van degenen die genade tonen.", "Een Quranische dua – voor vergeving en genade.", "Het laatste vers van Surah al-Mu'minun."),
        "dua_majlis_kaffarah" to DuaText("Kaffarat al-Majlis", "Glorie zij U, O Allah, en alle lof zij U. Ik getuig dat er geen god is behalve Jij. Ik zoek Uw vergeving en wend mij in berouw tot U.", "Bij het opstaan ​​van een bijeenkomst.", "Het wordt een boetedoening voor al het verkeerde dat tijdens de bijeenkomst is gezegd."),
        "dua_jami_forgiveness" to DuaText("Alomvattende vergeving", "O Allah, vergeef mij mijn fouten, mijn onwetendheid, mijn excessen in mijn zaken en alles wat U beter weet dan ik.", "Een uitgebreide dua van de Profeet ﷺ.", "De Profeet ﷺ maakte deze dua."),
        "dua_parents_nuh" to DuaText("Dua van Nuh (AS) voor ouders", "Mijn Heer, vergeef mij, mijn ouders, iedereen die als gelovige mijn huis binnenkomt, en alle gelovige mannen en gelovige vrouwen.", "Voor je ouders en de gelovigen.", "De dua van Profeet Noeh (AS)."),
        "dua_shukr_parents" to DuaText("Dankbaarheid voor ouders en rechtschapen nakomelingen", "Mijn Heer, stel mij in staat dankbaar te zijn voor Uw gunst die U mij en mijn ouders hebt geschonken, en rechtvaardige daden te doen die U behagen, en mijn nakomelingen rechtvaardig te maken. Ik wend mij vol berouw tot U en ik behoor tot degenen die zich onderwerpen.", "De Quranische dua van het bereiken van de leeftijd van veertig.", "Dankbaarheid, goede daden en de gerechtigheid van je kinderen – alles in één dua."),
        "dua_intimacy" to DuaText("Vóór huwelijksrelaties", "In de naam van Allah. O Allah, houd Shaytan weg van ons en houd Shaytan weg van wat (kinderen) U ons schenkt.", "Vóór huwelijksrelaties.", "Als een kind is verordend, zal Shaytan het nooit kwaad doen."),
        "dua_ibrahim_children_protection" to DuaText("Bescherming van huis en kinderen", "Mijn Heer, maak deze stad veilig en houd mij en mijn kinderen weg van het aanbidden van afgoden.", "De dua van profeet Ibrahim (AS) – voor de veiligheid van de stad en zijn kinderen.", "Een dua om standvastig te blijven op tawhid."),
        "dua_drinking_milk" to DuaText("Bij het drinken van melk", "O Allah, zegen het voor ons en geef ons er meer van.", "Bij het drinken van melk.", "Melk is zowel als voedsel als als drank voldoende."),
        "dua_iftar_host" to DuaText("Als je snel breekt met anderen", "Mogen vastende mensen samen met u hun vasten verbreken, mogen de rechtvaardigen uw voedsel eten en mogen de engelen voor u bidden.", "Bij het verbreken van het vasten bij iemand thuis.", "De ﷺ dua van de Profeet voor de gastheer."),
    )
}
